def restore_r08a_sources(draft, diagnostics):
    if git_blob(diagnostics.encode("utf-8")) != DIAGNOSTICS_LIVE:
        raise AssertionError("diagnostics owner changed")
    for block in (APPENDED, IMPORTS):
        if diagnostics.count(block) != 1:
            raise AssertionError("diagnostic inverse anchor changed")
        diagnostics = diagnostics.replace(block, "", 1)
    if git_blob(diagnostics.encode("utf-8")) != DIAGNOSTICS_PREVIOUS:
        raise AssertionError("prior diagnostics did not reconstruct")
    for current, prior, count in INVERSE:
        if draft.count(current) != count:
            raise AssertionError("draft inverse anchor changed: " + current[:100])
        draft = draft.replace(current, prior)
    if git_blob(draft.encode("utf-8")) != DRAFT_PREVIOUS:
        raise AssertionError("prior draft coordinator did not reconstruct")
    return draft, diagnostics

class PpR08DraftDiagnosticsMigrationTest(unittest.TestCase):
    def setUp(self):
        self.draft = (AI / "AiReplyDraftCoordinator.kt").read_text(encoding="utf-8")
        self.diagnostics = (AI / "AiModelCallDiagnostics.kt").read_text(encoding="utf-8")

    def test_exact_inverse_and_single_diagnostic_owner(self):
        draft, diagnostics = restore_r08a_sources(self.draft, self.diagnostics)
        self.assertEqual(DRAFT_PREVIOUS, git_blob(draft.encode("utf-8")))
        self.assertEqual(DIAGNOSTICS_PREVIOUS, git_blob(diagnostics.encode("utf-8")))
        for field in ("modelLifecycleTrace", "emittedSendTraceKeys"):
            declaration = r"\b(?:val|var)\s+" + field + r"\b"
            self.assertEqual(1, len(re.findall(declaration, self.diagnostics)))
            self.assertNotRegex(self.draft, declaration)
        self.assertEqual(1, self.diagnostics.count("internal object AiReplyTraceContract"))
        self.assertIn("AiReplyRequestTrace(lock, onDiagnosticLog, MAX_PROCESSED_KEYS, MAX_EMPTY_MODEL_RETRIES)", self.draft)
        for forbidden in ("TaskScheduler", "ChatDraftInputPort", "ChatDraftSendPort",
                          "ReplyTaskRepository", "TaskLease", "dispatchGesture("):
            self.assertNotIn(forbidden, self.diagnostics)

    def test_mutations_reject_stale_generation_terminal_duplication_or_lost_reset(self):
        for old, new in (
            ("it.requestGeneration == requestGeneration && !it.terminalLogged", "true"),
            ("trace.terminalLogged = true", "Unit"),
            ("emittedSendTraceKeys.clear()", "Unit"),
            ("terminal && !emittedSendTraceKeys.add(key)", "false"),
            ("runCatching { onDiagnosticLog(it) }", "onDiagnosticLog(it)"),
        ):
            self.assertIn(old, self.diagnostics)
            with self.subTest(old=old), self.assertRaises(AssertionError):
                restore_r08a_sources(self.draft, self.diagnostics.replace(old, new, 1))
        for old, new in (
            ("requestTrace.resetLocked()", "emptyList()"),
            ("requestTrace.beginLocked(requestId, policy.taskId, requestGeneration)", "Unit"),
            ("requestTrace.finishLocked(requestGeneration, reasonCode)", "null"),
        ):
            self.assertIn(old, self.draft)
            with self.subTest(old=old), self.assertRaises(AssertionError):
                restore_r08a_sources(self.draft.replace(old, new, 1), self.diagnostics)
